import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"world/GeneratorFactories","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"world/GeneratorFactories"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/world/GeneratorFactories/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/world/GeneratorFactories/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/world/GeneratorFactories/index.md","filePath":"api/@jsprismarine/prismarine/world/GeneratorFactories/index.md","lastUpdated":1794500225000}`),a={name:`api/@jsprismarine/prismarine/world/GeneratorFactories/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../../">API reference</a> / <a href="./../../">@jsprismarine/prismarine</a> / world/GeneratorFactories</p><h1 id="world-generatorfactories" tabindex="-1">world/GeneratorFactories <a class="header-anchor" href="#world-generatorfactories" aria-label="Permalink to “world/GeneratorFactories”">​</a></h1><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to “Classes”">​</a></h2><ul><li><a href="./classes/GeneratorFactories.html">GeneratorFactories</a></li></ul><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="generatorbuildcontext" tabindex="-1">GeneratorBuildContext <a class="header-anchor" href="#generatorbuildcontext" aria-label="Permalink to “GeneratorBuildContext”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L20" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:20</a></p><p>Everything a factory may read while building one dimension&#39;s generator.</p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="completionqueue" tabindex="-1">completionQueue? <a class="header-anchor" href="#completionqueue" aria-label="Permalink to “completionQueue?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>completionQueue?</strong>: <code>ChunkCompletionScheduler</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L39" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:39</a></p><p>Server-wide tick queue for non-gameplay work that finishes a generated chunk.</p><h5 id="content" tabindex="-1">content <a class="header-anchor" href="#content" aria-label="Permalink to “content”">​</a></h5><blockquote><p><code>readonly</code> <strong>content</strong>: () =&gt; <code>ServerContent</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L28" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:28</a></p><p>The server&#39;s loaded content, read when a block is placed.</p><h6 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h6><p><code>ServerContent</code></p><h5 id="dimension" tabindex="-1">dimension <a class="header-anchor" href="#dimension" aria-label="Permalink to “dimension”">​</a></h5><blockquote><p><code>readonly</code> <strong>dimension</strong>: <code>DimensionType</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L24" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:24</a></p><p>The dimension the generator fills, whose bounds every chunk takes.</p><h5 id="host" tabindex="-1">host? <a class="header-anchor" href="#host" aria-label="Permalink to “host?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>host?</strong>: <code>&quot;process&quot;</code> | <code>&quot;in-process&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L53" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:53</a></p><p>Where the workers run: <code>process</code> asks for a separate low-priority generation process and falls back to threads when it cannot start one. Absent means threads in this process.</p><h5 id="logger" tabindex="-1">logger <a class="header-anchor" href="#logger" aria-label="Permalink to “logger”">​</a></h5><blockquote><p><code>readonly</code> <strong>logger</strong>: <code>GeneratorLogger</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L37" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:37</a></p><p>Where a factory or its generator reports a decision a person should see.</p><h5 id="seed" tabindex="-1">seed <a class="header-anchor" href="#seed" aria-label="Permalink to “seed”">​</a></h5><blockquote><p><code>readonly</code> <strong>seed</strong>: <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L26" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:26</a></p><p>The world seed. A generator that is seeded per chunk request may ignore it.</p><h5 id="stem" tabindex="-1">stem <a class="header-anchor" href="#stem" aria-label="Permalink to “stem”">​</a></h5><blockquote><p><code>readonly</code> <strong>stem</strong>: <a href="./../../../worldgen/#levelstem"><code>LevelStem</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L22" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:22</a></p><p>The stem naming the generator kind and its settings.</p><h5 id="terraincache" tabindex="-1">terrainCache? <a class="header-anchor" href="#terraincache" aria-label="Permalink to “terrainCache?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>terrainCache?</strong>: <a href="#terraincachesettings"><code>TerrainCacheSettings</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L60" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:60</a></p><p>Where generated terrain tiles are kept between runs, and how much room they may take.</p><p>Absent keeps every tile in memory only. Like <code>workers</code>, the noise factory reads it once, from the first stem it builds, because one generator serves every dimension.</p><h5 id="workers" tabindex="-1">workers? <a class="header-anchor" href="#workers" aria-label="Permalink to “workers?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>workers?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L48" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:48</a></p><p>How many worker threads the generator may start.</p><p>Defaults to the host&#39;s share, <code>min(6, cores - 2)</code>. Zero keeps generation on the calling thread, which is what a test wants and what a host too small for a worker gets anyway. The noise factory shares one pool between every stem it builds, so the first stem&#39;s value sizes it and later ones are not read.</p><h5 id="worldgen" tabindex="-1">worldgen <a class="header-anchor" href="#worldgen" aria-label="Permalink to “worldgen”">​</a></h5><blockquote><p><code>readonly</code> <strong>worldgen</strong>: () =&gt; <code>JavaWorldgenRegistries</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L35" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:35</a></p><p>Java&#39;s world generation registries.</p><p>A function, because reading them costs about 1500 JSON files and a flat or void dimension never needs them. Throws when the Java data is not on disk.</p><h6 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h6><p><code>JavaWorldgenRegistries</code></p><hr><h3 id="generatorfactory" tabindex="-1">GeneratorFactory <a class="header-anchor" href="#generatorfactory" aria-label="Permalink to “GeneratorFactory”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L74" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:74</a></p><p>Builds the generator for one kind of stem.</p><h4 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to “Properties”">​</a></h4><h5 id="kind" tabindex="-1">kind <a class="header-anchor" href="#kind" aria-label="Permalink to “kind”">​</a></h5><blockquote><p><code>readonly</code> <strong>kind</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L76" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:76</a></p><p>The generator kind this factory answers, as a stem&#39;s <code>generator.type</code> spells it.</p><h4 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h4><h5 id="build" tabindex="-1">build() <a class="header-anchor" href="#build" aria-label="Permalink to “build()”">​</a></h5><blockquote><p><strong>build</strong>(<code>context</code>): <code>Generator</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L83" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:83</a></p><p>Builds a generator for one dimension.</p><h6 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="context" tabindex="-1">context <a class="header-anchor" href="#context" aria-label="Permalink to “context”">​</a></h6><p><a href="#generatorbuildcontext"><code>GeneratorBuildContext</code></a></p><h6 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h6><p><code>Generator</code></p><h6 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h6><p>When the stem&#39;s settings cannot be honored, which is the moment a misconfigured world should fail rather than at its first chunk.</p><hr><h3 id="terraincachesettings" tabindex="-1">TerrainCacheSettings <a class="header-anchor" href="#terraincachesettings" aria-label="Permalink to “TerrainCacheSettings”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L64" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:64</a></p><p>A disk budget for generated terrain tiles.</p><h4 id="properties-2" tabindex="-1">Properties <a class="header-anchor" href="#properties-2" aria-label="Permalink to “Properties”">​</a></h4><h5 id="codeversion" tabindex="-1">codeVersion <a class="header-anchor" href="#codeversion" aria-label="Permalink to “codeVersion”">​</a></h5><blockquote><p><code>readonly</code> <strong>codeVersion</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L70" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:70</a></p><p>Identifies the code that builds the tiles, so an upgrade does not reuse older records.</p><h5 id="directory" tabindex="-1">directory <a class="header-anchor" href="#directory" aria-label="Permalink to “directory”">​</a></h5><blockquote><p><code>readonly</code> <strong>directory</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L66" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:66</a></p><p>A directory used only for terrain records.</p><h5 id="maxbytes" tabindex="-1">maxBytes <a class="header-anchor" href="#maxbytes" aria-label="Permalink to “maxBytes”">​</a></h5><blockquote><p><code>readonly</code> <strong>maxBytes</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf5a18673631e1df5d01453fb5c6d3608ef6a53a/packages/prismarine/src/world/GeneratorFactories.ts#L68" target="_blank" rel="noreferrer">prismarine/src/world/GeneratorFactories.ts:68</a></p><p>The most bytes the records may take.</p>`,94)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};